// Inicio rápido
import { Button } from 'v12-ui';
import 'v12-ui/styles.css';

<Button variant='primary'>Clic aquí</Button>

// Tree-shakeable - solo importa lo que usas
import { Button, Stack } from 'v12-ui';
import 'v12-ui/styles.css';

// npm i v12-ui

// Button se adapta al contexto
<Button variant='primary'>Button</Button>
<Button as='a' href='/docs'>Enlace</Button>

// Text y Stack son polimórficos
<Text as='h1' variant='hero'>Título</Text>
<Stack as='section' direction='col'>Contenido</Stack>

// MagicText - partículas forman texto
<MagicText text='Hola' colors={['#0d9488', '#14b8a6']} />

// MagicMouseFollower - estela de partículas
<MagicMouseFollower particleCount={30} />

// Toggle - switch WAI-ARIA
<Toggle aria-label='Activar notificaciones' />

// Select - combobox WAI-ARIA
<Select aria-label='Elige una opción'>
  <Select.Option value='1'>Opción 1</Select.Option>
</Select>

// Redis almacena refresh tokens activos
// Al refrescar: token anterior se invalida (rotación)
// Si roban un token, el siguiente refresh lo detecta

.card-inner {
  transition: transform 0.6s;
  transform-style: preserve-3d;
}
.card.flipped .card-inner {
  transform: rotateY(180deg);
}
